SELECT * FROM the_full_order.tb_supplier WHERE supplier_type<>'DIRECT'
AND supplier_id=#{supplier_id}
AND active_yn=#{active_yn}
ORDER BY supplier_name

SELECT * FROM the_full_order.tb_supplier_ingredient_price_history WHERE 1=1
AND price_history_id=#{price_history_id}
AND supplier_product_id=#{supplier_product_id}
ORDER BY effective_from DESC
